class Solution:
    def count_pairs(self, a):
        n = len(a)
        left = [-1] * n
        right = [n] * n
        stack = []

        # Previous greater element
        for i in range(n):
            while stack and a[stack[-1]] < a[i]:
                stack.pop()
            left[i] = stack[-1] if stack else -1
            stack.append(i)

        stack.clear()

        # Next greater element
        for i in range(n - 1, -1, -1):
            while stack and a[stack[-1]] < a[i]:
                stack.pop()
            right[i] = stack[-1] if stack else n
            stack.append(i)

        ans = 0

        # Process each index as maximum
        for i in range(n):
            l = left[i] + 1
            r = right[i] - 1

            for x in range(l, i + 1):
                for y in range(i + 1, r + 1):
                    if a[x] * a[y] <= a[i]:
                        ans += 1

        return ans
